function FarmMap({ user }) {
  const mapRef = useRef(null);
  const mapInstance = useRef(null);
  const [loaded, setLoaded] = useState(false);
  const [farms, setFarms] = useState(user.farms || []);
  const [addMode, setAddMode] = useState(false);
  const [formFarm, setFormFarm] = useState({ name:"", crop:"", size:"", soilType:"Red", status:"Healthy" });
  const [weather, setWeather] = useState(null);

  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    const css = document.createElement("link");
    css.rel = "stylesheet"; css.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(css);
    document.head.appendChild(script);
    script.onload = () => setLoaded(true);
    return () => { document.head.removeChild(script); };
  }, []);

  useEffect(() => {
    if (!loaded || !mapRef.current || mapInstance.current) return;
    const L = window.L;
    const lat = user.lat || 9.9252, lon = user.lon || 78.1198;
    const map = L.map(mapRef.current, { zoomControl:true }).setView([lat, lon], 13);
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", { attribution:"© OpenStreetMap contributors" }).addTo(map);

    // User location marker
    const icon = L.divIcon({ html:`<div style="background:${C.bg2};width:14px;height:14px;border-radius:50%;border:3px solid white;box-shadow:0 2px 6px rgba(0,0,0,0.4)"></div>`, iconSize:[20,20], iconAnchor:[10,10] });
    L.marker([lat, lon], { icon }).addTo(map).bindPopup(`<b>📍 ${user.name}</b><br>${user.district}, Tamil Nadu<br>Land: ${user.landSize||"?"} acres`);

    // Add farm markers
    farms.forEach(farm => {
      if (farm.lat && farm.lon) {
        const fc = farm.status === "Healthy" ? "#1a7a3a" : farm.status === "Disease Alert" ? "#b83232" : "#c87010";
        const fi = L.divIcon({ html:`<div style="background:${fc};color:#fff;padding:4px 8px;border-radius:6px;font-size:11px;font-weight:600;white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,0.3)">${farm.crop}</div>`, className:"" });
        L.marker([farm.lat, farm.lon], { icon:fi }).addTo(map).bindPopup(`<b>${farm.name}</b><br>Crop: ${farm.crop}<br>Size: ${farm.size} acres<br>Status: ${farm.status}`);
      }
    });

    map.on("click", (e) => {
      if (addMode) {
        const coords = e.latlng;
        setFormFarm(p => ({ ...p, clickedLat:coords.lat, clickedLon:coords.lng }));
      }
    });

    mapInstance.current = map;
  }, [loaded]);

  const addFarm = () => {
    if (!formFarm.name || !formFarm.crop) return;
    const lat = formFarm.clickedLat || (user.lat || 9.9252) + (Math.random()-0.5)*0.02;
    const lon = formFarm.clickedLon || (user.lon || 78.1198) + (Math.random()-0.5)*0.02;
    const farm = { id:Date.now(), ...formFarm, lat, lon, addedOn:new Date().toLocaleDateString("en-IN") };
    const updated = [...farms, farm];
    setFarms(updated);
    const users = S.get("users")||[];
    const idx = users.findIndex(u=>u.id===user.id);
    if (idx>=0) { users[idx].farms=updated; S.set("users",users); S.set("current_user",users[idx]); }
    if (mapInstance.current && window.L) {
      const fc = farm.status==="Healthy"?"#1a7a3a":farm.status==="Disease Alert"?"#b83232":"#c87010";
      const fi = window.L.divIcon({ html:`<div style="background:${fc};color:#fff;padding:4px 8px;border-radius:6px;font-size:11px;font-weight:600;box-shadow:0 2px 6px rgba(0,0,0,0.3)">${farm.crop}</div>`, className:"" });
      window.L.marker([lat,lon],{icon:fi}).addTo(mapInstance.current).bindPopup(`<b>${farm.name}</b><br>Crop: ${farm.crop}<br>Size: ${farm.size} acres`);
    }
    setAddMode(false);
    setFormFarm({ name:"", crop:"", size:"", soilType:"Red", status:"Healthy" });
  };

  const statusColor = { "Healthy":C.bg2, "Disease Alert":C.red, "Monitor":C.orange };

  return (
    <div style={{ padding:20 }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:16 }}>
        <div>
          <h1 style={{ fontSize:22, fontWeight:600, color:C.text, margin:0 }}>🗺️ My Farm Map</h1>
          <p style={{ color:C.muted, fontSize:13, margin:"4px 0 0" }}>Track your agricultural land — status, crops, soil health</p>
        </div>
        <Btn onClick={() => setAddMode(!addMode)} variant={addMode?"amber":"primary"}>{addMode ? "📌 Click map to place farm" : "+ Add Farm"}</Btn>
      </div>

      {addMode && (
        <Card style={{ marginBottom:12, background:C.amberPale, border:`1px solid #e0c060` }}>
          <div style={{ fontSize:13, fontWeight:600, color:C.amber, marginBottom:10 }}>📌 Add New Farm Plot</div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:10 }}>
            <Input label="Farm Name" value={formFarm.name} onChange={e=>setFormFarm(p=>({...p,name:e.target.value}))} placeholder="e.g. North Field" />
            <Input label="Crop" value={formFarm.crop} onChange={e=>setFormFarm(p=>({...p,crop:e.target.value}))} options={CROPS_ALL} />
            <Input label="Size (Acres)" type="number" value={formFarm.size} onChange={e=>setFormFarm(p=>({...p,size:e.target.value}))} placeholder="e.g. 2.5" />
            <Input label="Soil Type" value={formFarm.soilType} onChange={e=>setFormFarm(p=>({...p,soilType:e.target.value}))} options={["Red","Black","Loamy","Sandy","Clay","Alluvial"]} />
            <Input label="Current Status" value={formFarm.status} onChange={e=>setFormFarm(p=>({...p,status:e.target.value}))} options={["Healthy","Disease Alert","Monitor","Harvested","Fallow"]} />
          </div>
          <div style={{ display:"flex", gap:8, marginTop:4 }}>
            <Btn onClick={addFarm} style={{ padding:"8px 20px" }}>✅ Save Farm</Btn>
            <Btn variant="ghost" onClick={() => setAddMode(false)} style={{ padding:"8px 20px" }}>Cancel</Btn>
          </div>
          <div style={{ fontSize:11.5, color:C.amber, marginTop:8 }}>💡 Tip: Click on the map below to place your farm at exact location</div>
        </Card>
      )}

      <div style={{ display:"grid", gridTemplateColumns:"1fr 300px", gap:14 }}>
        <Card style={{ padding:0, overflow:"hidden" }}>
          {!loaded && <div style={{ height:460, display:"flex", alignItems:"center", justifyContent:"center", color:C.muted }}>Loading map…</div>}
          <div ref={mapRef} style={{ height:460, display:loaded?"block":"none" }} />
        </Card>

        <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
          <Card style={{ padding:12 }}>
            <div style={{ fontSize:12.5, fontWeight:600, color:C.text, marginBottom:8 }}>My Farm Plots ({farms.length})</div>
            {farms.length === 0 && <div style={{ fontSize:12, color:C.muted, textAlign:"center", padding:"16px 0" }}>No farms added yet.<br/>Click "+ Add Farm" to start</div>}
            {farms.map(f => (
              <div key={f.id} style={{ padding:"8px 0", borderBottom:`1px solid ${C.border}`, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div>
                  <div style={{ fontSize:13, fontWeight:500, color:C.text }}>{f.name}</div>
                  <div style={{ fontSize:11, color:C.muted }}>{f.crop} • {f.size} acres • {f.soilType} soil</div>
                  <div style={{ fontSize:11, color:C.muted }}>{f.addedOn}</div>
                </div>
                <Badge color={statusColor[f.status]||C.muted} bg={f.status==="Healthy"?C.pale:f.status==="Disease Alert"?C.redPale:C.orangePale}>{f.status}</Badge>
              </div>
            ))}
          </Card>

          <Card style={{ padding:12, background:C.pale }}>
            <div style={{ fontSize:12.5, fontWeight:600, color:C.text, marginBottom:8 }}>🌡️ Field Conditions Today</div>
            {[
              { label:"Temperature", val:"32°C", risk:"Low" },
              { label:"Humidity", val:"72%", risk:"Medium" },
              { label:"Pest Risk", val:"Moderate", risk:"Medium" },
              { label:"Disease Risk", val:"High", risk:"High" },
              { label:"Irrigation Need", val:"Tomorrow 6 AM", risk:"" },
            ].map(r => (
              <div key={r.label} style={{ display:"flex", justifyContent:"space-between", marginBottom:6, fontSize:12.5 }}>
                <span style={{ color:C.muted }}>{r.label}</span>
                <span style={{ fontWeight:500, color:r.risk==="High"?C.red:r.risk==="Medium"?C.orange:C.text }}>{r.val}</span>
              </div>
            ))}
          </Card>

          <Card style={{ padding:12, background:"linear-gradient(135deg,#0e3a1c,#062010)", border:"none" }}>
            <div style={{ fontSize:13, fontWeight:600, color:"#fff", marginBottom:6 }}>📡 NDVI Satellite Status</div>
            <div style={{ fontSize:12, color:"rgba(255,255,255,0.7)", lineHeight:1.5 }}>Crop health index: <span style={{color:"#5de87a",fontWeight:600}}>0.72 (Good)</span><br/>Last satellite pass: Today 10:32 AM<br/>Cloud cover: 18%</div>
            <div style={{ marginTop:10, display:"flex", gap:6 }}>
              {[{c:"#1a7a3a",l:"Healthy"},{c:"#c87010",l:"Stress"},{c:"#b83232",l:"Alert"}].map(s => (
                <div key={s.l} style={{ display:"flex", alignItems:"center", gap:4, fontSize:10.5, color:"rgba(255,255,255,0.6)" }}>
                  <div style={{ width:8,height:8,borderRadius:2,background:s.c }} />{s.l}
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}
